-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.bookmarks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    "userId" uuid NOT NULL,
    "resourceType" character varying(255) NOT NULL,
    "resourceId" character varying(255) NOT NULL,
    folder character varying(255),
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: coin_price_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coin_price_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    coin_id uuid NOT NULL,
    "interval" text DEFAULT '1h'::text NOT NULL,
    price numeric(24,8) NOT NULL,
    "timestamp" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: coins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    symbol text NOT NULL,
    name text NOT NULL,
    market_cap_rank integer,
    current_price numeric(24,8) DEFAULT 0 NOT NULL,
    market_cap_usd numeric(24,2) DEFAULT 0 NOT NULL,
    market_cap numeric(24,2) DEFAULT 0 NOT NULL,
    volume_24h_usd numeric(24,2) DEFAULT 0 NOT NULL,
    volume_24h numeric(24,2) DEFAULT 0 NOT NULL,
    change_1h_pct numeric(10,4) DEFAULT 0 NOT NULL,
    change_24h_pct numeric(10,4) DEFAULT 0 NOT NULL,
    price_change_24h_pct numeric(10,4) DEFAULT 0 NOT NULL,
    change_7d_pct numeric(10,4) DEFAULT 0 NOT NULL,
    change_30d_pct numeric(10,4) DEFAULT 0 NOT NULL,
    circulating_supply numeric(28,4),
    total_supply numeric(28,4),
    max_supply numeric(28,4),
    ath_usd numeric(24,8),
    atl_usd numeric(24,8),
    fully_diluted_valuation_usd numeric(24,2),
    sparkline_7d jsonb,
    history_30d jsonb,
    description text,
    links jsonb,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: crypto_holdings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crypto_holdings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    coin_id uuid,
    symbol text NOT NULL,
    name text,
    amount numeric(28,8) DEFAULT 0 NOT NULL,
    avg_buy_price numeric(24,8) DEFAULT 0 NOT NULL,
    total_cost numeric(24,4) DEFAULT 0 NOT NULL,
    cost_basis_usd numeric(24,4) DEFAULT 0 NOT NULL,
    current_value numeric(24,4) DEFAULT 0 NOT NULL,
    current_value_usd numeric(24,4) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone
);


--
-- Name: crypto_news; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crypto_news (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    source text,
    summary text,
    url text NOT NULL,
    related_symbols jsonb,
    signal text DEFAULT 'neutral'::text NOT NULL,
    published_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: crypto_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crypto_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    symbol text NOT NULL,
    kind text DEFAULT 'buy'::text NOT NULL,
    amount numeric(28,8) DEFAULT 0 NOT NULL,
    price_usd numeric(24,8) DEFAULT 0 NOT NULL,
    fee_usd numeric(24,4) DEFAULT 0 NOT NULL,
    exchange text,
    total_usd numeric(24,4) DEFAULT 0 NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: crypto_watchlist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crypto_watchlist (
