);


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL DEFAULT 'system_message',
    title text NOT NULL DEFAULT '',
    body text NOT NULL DEFAULT '',
    href text,
    unread boolean NOT NULL DEFAULT true,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: user_preferences; Type: TABLE; Schema: public; Owner: -
--
-- App-level user settings for crypto-tracker (display name override,
-- preferred quote currency, locale, refresh interval). One row per user.
CREATE TABLE public.user_preferences (
    user_id uuid PRIMARY KEY,
    display_name text,
    quote_currency text NOT NULL DEFAULT 'USD',
    locale text NOT NULL DEFAULT 'en-US',
    refresh_seconds integer NOT NULL DEFAULT 15,
    theme text NOT NULL DEFAULT 'system',
    notify_email boolean NOT NULL DEFAULT true,
    notify_push boolean NOT NULL DEFAULT false,
    notify_sms boolean NOT NULL DEFAULT false,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: price_alerts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.price_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    coin_id uuid,
    symbol text NOT NULL,
    condition text DEFAULT 'above'::text NOT NULL,
    target_price numeric(24,8),
    is_active boolean DEFAULT true NOT NULL,
    channels jsonb DEFAULT '["email"]'::jsonb NOT NULL,
    repeat text DEFAULT 'one-time'::text NOT NULL,
    notes text,
    triggered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


